function resetImageAsset(asset){s.imageAsset=asset;imageCache=null;imagePending=null;controls();schedule()}
async function importImageFile(f){if(!f)return;const owner=s,ticket=++uploadEpoch;if(f.size>32*1024*1024)return toast('Choisissez une photo de moins de 32 Mo.');let bitmap;try{bitmap=await createImageBitmap(f);const {canvas,w,h}=imageReadBitmap(bitmap);if(owner!==s||ticket!==uploadEpoch||s.engine!=='image')return;resetImageAsset({url:canvas.toDataURL('image/jpeg',.93),w,h,name:f.name});toast('Photo chargée · traitement local')}catch{toast('Photo illisible. Essayez un JPG, PNG ou WebP.')}finally{bitmap?.close()}}
