function imageDemo(){const w=480,h=540,gray=new Uint8Array(w*h);for(let y=0;y<h;y++)for(let x=0;x<w;x++){const u=x/w,v=y/h;let L=.97-.35*Math.exp(-((u-.52)**2/.07+(v-.77)**2/.003));for(const [cx,cy,rad]of [[.59,.57,.235],[.32,.70,.105],[.47,.32,.10]]){const nx=(u-cx)/rad,ny=(v-cy)*h/w/rad,d=nx*nx+ny*ny;if(d<1){const nz=Math.sqrt(1-d);L=.13+.82*imgClamp(-.55*nx-.66*ny+.50*nz);}}gray[y*w+x]=Math.round(255*L)}return {w,h,gray}}
