 if(s.engine==='op'&&s.params.mode==='image'){s.engine='image';s.params={...imageDefaults,mode:'scan',angle:s.params.orientation==='vertical'?90:0,contrast:old?.contrast||1,invert:!!old?.invert,fit:old?.fit||'cover'}}
